with enriched as (select src.*, p.device from web_events src left join sessions p on src.session_id = p.id) select date_trunc('quarter', event_time) as quarter_start, count(distinct id) as distinct_ids, round(avg(duration_sec), 2) as avg_duration_sec, round(sum(duration_sec) / nullif(count(case when page = '/search' then 1 end), 0), 2) as duration_sec_per_search, size(collect_set(device)) as num_devices, min(event_time) as started_at from enriched group by date_trunc('quarter', event_time) order by quarter_start desc nulls first;
